/* SOURCE: src/tokens.css */
/* Author: @jiuyi0204 | 月桂印刷所视觉令牌。未经许可禁止二改二传。 */
:root {
    --laurel-shell: #142c24;
    --laurel-shell-raised: #1d3a30;
    --laurel-shell-deep: #0d211b;
    --laurel-paper: #f3ecd9;
    --laurel-paper-soft: #e8ddc3;
    --laurel-paper-muted: #d8c9a8;
    --laurel-paper-disabled: #c9bea6;
    --laurel-text: #263128;
    --laurel-text-soft: #62685d;
    --laurel-text-disabled: #817f70;
    --laurel-text-on-dark: #f3ebd8;
    --laurel-brass: #ad7d37;
    --laurel-brass-deep: #725024;
    --laurel-border: #9b8159;
    --laurel-border-soft: #c5b58f;
    --laurel-selection: #d5bf82;
    --laurel-focus: #e1ae4d;
    --laurel-info: #315e69;
    --laurel-success: #3f6d4d;
    --laurel-warning: #966727;
    --laurel-error: #8f4438;
    --laurel-transparent: transparent;
    --laurel-radius-sm: 5px;
    --laurel-radius-md: 9px;
    --laurel-radius-lg: 14px;
    --laurel-gap-xs: 0.3rem;
    --laurel-gap-sm: 0.55rem;
    --laurel-gap-md: 0.9rem;
    --laurel-gap-lg: 1.3rem;
    --laurel-font-body: ui-serif, "Noto Serif SC", "Songti SC", serif;
    --laurel-font-ui: ui-sans-serif, system-ui, "Microsoft YaHei UI", sans-serif;
    --laurel-font-size-body: 1em;
    --laurel-font-size-user: 0.98em;
    --laurel-font-size-character: 1em;
    --laurel-font-size-meta: 0.82em;
    --laurel-font-size-input: 1em;
    --laurel-reading-width: 72ch;
}

/* SOURCE: src/kernel/app-shell.css */
/* W00 应用外壳：仅统一视觉，不改写应用骨架。 */
body {
    color: var(--laurel-text-on-dark);
    background: linear-gradient(135deg, var(--laurel-shell-deep), var(--laurel-shell));
    font-family: var(--laurel-font-ui);
}

#sheld,
#main,
#form_sheld {
    color: var(--laurel-text-on-dark);
}

::selection {
    color: var(--laurel-text);
    background-color: var(--laurel-selection);
}

/* SOURCE: src/chat-layout.css */
/* W01 主聊天：原生 Flex 与真实数据不变，建立紧凑题签 + 长文纸页。 */
#chat {
    color: var(--laurel-text);
    background: linear-gradient(90deg, var(--laurel-shell-deep), var(--laurel-shell-raised), var(--laurel-shell-deep));
    padding: var(--laurel-gap-md);
}

#chat .mes {
    color: var(--laurel-text);
    background-color: var(--laurel-paper);
    border: 1px solid var(--laurel-border);
    border-radius: var(--laurel-radius-sm);
    margin-block: var(--laurel-gap-md);
    padding: var(--laurel-gap-md);
    align-items: flex-start;
}

#chat .mes[is_user="true"] {
    background-color: var(--laurel-paper-muted);
    border-left: 4px solid var(--laurel-brass-deep);
    margin-inline-start: clamp(0rem, 7vw, 6rem);
}

#chat .mes[is_user="false"][is_system="false"] {
    background: linear-gradient(90deg, var(--laurel-paper), var(--laurel-paper-soft));
    border-top: 3px double var(--laurel-border);
    border-bottom: 3px double var(--laurel-border);
}

#chat .mes[is_system="true"],
#chat .smallSysMes {
    color: var(--laurel-text-on-dark);
    background-color: var(--laurel-shell-raised);
    border-color: var(--laurel-brass);
}

#chat .mes_block {
    min-width: 0;
}

#chat .mesAvatarWrapper {
    margin-inline-end: var(--laurel-gap-md);
}

#chat .avatar {
    background-color: var(--laurel-paper-soft);
    border: 2px solid var(--laurel-brass);
    border-radius: var(--laurel-radius-sm);
    padding: 2px;
}

#chat .avatar img {
    border-radius: calc(var(--laurel-radius-sm) - 2px);
}

#chat .ch_name,
#chat .name_text {
    color: var(--laurel-brass-deep);
    font-family: var(--laurel-font-body);
    letter-spacing: 0.08em;
}

#chat .timestamp,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay {
    color: var(--laurel-text-soft);
    font-size: var(--laurel-font-size-meta);
    font-variant-numeric: tabular-nums;
}

#chat .mes_bias,
#chat .mes_timer,
#chat .mes_token_count {
    color: var(--laurel-text-soft);
}

#chat .swipe_left,
#chat .swipe_right {
    color: var(--laurel-brass-deep);
}

/* SOURCE: src/full-text.css */
/* W01 全文排版：只处理正文语义节点，不补偿父级几何。 */
#chat .mes_text {
    color: var(--laurel-text);
    font-family: var(--laurel-font-body);
    font-size: var(--laurel-font-size-body);
    font-weight: 400;
    line-height: 1.9;
    max-width: var(--laurel-reading-width);
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    font-size: var(--laurel-font-size-user);
    line-height: 1.65;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    font-size: var(--laurel-font-size-character);
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    color: var(--laurel-brass-deep);
    font-family: var(--laurel-font-body);
    font-weight: 400;
    letter-spacing: 0.06em;
    border-bottom: 1px solid var(--laurel-border-soft);
}

#chat .mes_text :is(strong, b) {
    color: var(--laurel-brass-deep);
    font-weight: 400;
    letter-spacing: 0.035em;
}

#chat .mes_text a {
    color: var(--laurel-info);
    text-decoration-color: var(--laurel-brass);
}

#chat .mes_text blockquote {
    color: var(--laurel-text-soft);
    background-color: var(--laurel-paper-soft);
    border-left: 3px solid var(--laurel-brass);
    margin-inline: 0;
    padding: var(--laurel-gap-sm) var(--laurel-gap-md);
}

#chat .mes_text :is(code, pre) {
    color: var(--laurel-text-on-dark);
    background-color: var(--laurel-shell);
    border: 1px solid var(--laurel-border);
}

#chat .mes_text pre {
    max-width: 100%;
    overflow-x: auto;
    padding: var(--laurel-gap-md);
}

#chat .mes_text table {
    max-width: 100%;
    border-collapse: collapse;
    background-color: var(--laurel-paper-soft);
}

#chat .mes_text :is(th, td) {
    border: 1px solid var(--laurel-border-soft);
    padding: var(--laurel-gap-sm);
}

#chat .mes_text img {
    max-width: 100%;
    height: auto;
    border: 1px solid var(--laurel-border);
    border-radius: var(--laurel-radius-sm);
}

/* SOURCE: src/windows/shared-panels.css */
/* W04-W12 共同母版：各窗口仍由稳定根节点限制作用域。 */
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) {
    color: var(--laurel-text-on-dark);
    background-color: var(--laurel-shell-deep);
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) .drawer-content {
    color: var(--laurel-text);
    background: linear-gradient(90deg, var(--laurel-paper), var(--laurel-paper-soft));
    border: 1px solid var(--laurel-border);
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(h2, h3, h4, label, .title) {
    color: var(--laurel-brass-deep);
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.inline-drawer-content, .range-block, .world_entry, .extension_block, .persona_block, .character_select) {
    color: var(--laurel-text);
    background-color: var(--laurel-paper-soft);
    border-color: var(--laurel-border-soft);
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) .menu_button {
    color: var(--laurel-text-on-dark);
    background-color: var(--laurel-shell-raised);
    border-color: var(--laurel-brass);
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) .menu_button:hover {
    color: var(--laurel-text);
    background-color: var(--laurel-selection);
    border-color: var(--laurel-brass-deep);
}

/* SOURCE: src/windows/w02-topbar.css */
/* W02 顶栏：仅入口触发层，不改 .drawer 几何。 */
#top-settings-holder {
    min-height: 44px;
