    gap: var(--laurel-gap-sm);
    min-height: 52px;
    padding: var(--laurel-gap-sm);
    border-radius: var(--laurel-radius-md) var(--laurel-radius-md) 0 0;
}

#send_textarea {
    min-height: 38px;
    max-height: min(38vh, 18rem);
    padding: var(--laurel-gap-sm) var(--laurel-gap-md);
    border-radius: var(--laurel-radius-sm);
    line-height: 1.55;
}

#leftSendForm,
#rightSendForm {
    gap: var(--laurel-gap-xs);
    align-items: center;
}

#send_form .menu_button,
#send_but {
    min-width: 40px;
    min-height: 40px;
    border-radius: var(--laurel-radius-sm);
}

