.popup-content {
    border-radius: var(--laurel-radius-md);
    padding: var(--laurel-gap-md);
}

#toast-container .toast {
    border-radius: var(--laurel-radius-sm);
    padding: var(--laurel-gap-md);
}

.select2-dropdown {
    border-radius: var(--laurel-radius-sm);
}

/* SOURCE: src/windows/state-controls.css */
/* v5 视觉状态合同的唯一 CSS 实现源。 */

/* reasoning_block */
.mes_reasoning_details {
    color: var(--laurel-text);
    background-color: var(--laurel-paper-soft);
    border: 1px solid var(--laurel-border);
}
.mes_reasoning_details:not([open]) { background-color: var(--laurel-paper-muted); }
.mes_reasoning_details[open] { background-color: var(--laurel-paper); }
.mes_reasoning_details.thinking { border-color: var(--laurel-warning); }
.mes_reasoning_details.done { border-color: var(--laurel-success); }
.mes_reasoning_details:focus-within { outline: 2px solid var(--laurel-focus); }
.mes_reasoning_details .mes_reasoning { color: var(--laurel-text); }
.mes_reasoning_details summary { color: var(--laurel-brass-deep); }

/* prompt_manager */
#completion_prompt_manager .prompt_manager_entry {
    color: var(--laurel-text);
    background-color: var(--laurel-paper-soft);
    border: 1px solid var(--laurel-border-soft);
}
#completion_prompt_manager .prompt_manager_entry.disabled {
    color: var(--laurel-text-disabled);
    background-color: var(--laurel-paper-disabled);
}
#completion_prompt_manager .prompt_manager_entry.selected {
    background-color: var(--laurel-selection);
    border-color: var(--laurel-brass-deep);
}
#completion_prompt_manager .prompt_manager_entry:not(.selected) { background-color: var(--laurel-paper-soft); }
#completion_prompt_manager .prompt_manager_entry:hover { border-color: var(--laurel-brass); }
#completion_prompt_manager .prompt_manager_entry:focus-visible { outline: 2px solid var(--laurel-focus); }
#completion_prompt_manager .prompt_manager_entry:not(.expanded) { color: var(--laurel-text); }
#completion_prompt_manager .prompt_manager_entry.expanded { background-color: var(--laurel-paper); }
#completion_prompt_manager .prompt_manager_entry.disabled .prompt_manager_name { color: var(--laurel-text-disabled); }
#completion_prompt_manager .prompt_manager_entry.disabled .prompt_manager_type { color: var(--laurel-text-disabled); }
#completion_prompt_manager .prompt_manager_entry.disabled .prompt_manager_edit { color: var(--laurel-text-disabled); }
#completion_prompt_manager .prompt_manager_entry.disabled input[type="checkbox"] { accent-color: var(--laurel-brass-deep); color: var(--laurel-text-disabled); }
#completion_prompt_manager .prompt_manager_entry.disabled .prompt_manager_tokens { color: var(--laurel-text-disabled); }

/* select2 */
.select2-container .select2-selection__choice {
    color: var(--laurel-text);
    background-color: var(--laurel-paper-muted);
    border-color: var(--laurel-border);
}
.select2-dropdown .select2-results__option--selected { background-color: var(--laurel-selection); }
.select2-dropdown .select2-results__option:not(.select2-results__option--selected) { background-color: var(--laurel-paper); }
.select2-dropdown .select2-results__option--highlighted { color: var(--laurel-text-on-dark); background-color: var(--laurel-shell-raised); }
.select2-container .select2-selection:focus-visible { outline: 2px solid var(--laurel-focus); }
.select2-container--disabled .select2-selection {
    color: var(--laurel-text-disabled);
    background-color: var(--laurel-paper-disabled);
    border-color: var(--laurel-border-soft);
}
.select2-container .select2-selection__rendered { color: var(--laurel-text); }
.select2-container .select2-selection__choice__remove { color: var(--laurel-brass-deep); }
.select2-container--open .select2-selection { border-color: var(--laurel-brass); }

/* text_fields */
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) :is(input[type="text"], input[type="number"], input[type="password"], textarea, select) {
    color: var(--laurel-text);
    background-color: var(--laurel-paper);
    border-color: var(--laurel-border);
    caret-color: var(--laurel-brass-deep);
}
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) :is(input[type="text"], input[type="number"], input[type="password"], textarea, select):disabled {
    color: var(--laurel-text-disabled);
    background-color: var(--laurel-paper-disabled);
    border-color: var(--laurel-border-soft);
}
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) :is(input[type="text"], input[type="number"], input[type="password"], textarea, select):focus-visible { outline: 2px solid var(--laurel-focus); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) :is(input[type="text"], input[type="number"], input[type="password"], textarea)::placeholder { color: var(--laurel-text-soft); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) :is(input[type="text"], input[type="number"], input[type="password"], textarea):disabled::placeholder { color: var(--laurel-text-disabled); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) option { color: var(--laurel-text); background-color: var(--laurel-paper); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) option:checked { color: var(--laurel-text); background-color: var(--laurel-selection); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) option:disabled { color: var(--laurel-text-disabled); background-color: var(--laurel-paper-disabled); }

/* choice_controls */
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) input[type="checkbox"]:not(:checked) { color: var(--laurel-brass-deep); accent-color: var(--laurel-brass); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) input[type="checkbox"]:checked { color: var(--laurel-text-on-dark); accent-color: var(--laurel-brass-deep); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) input[type="checkbox"]:disabled { color: var(--laurel-text-disabled); accent-color: var(--laurel-border-soft); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) input[type="checkbox"]:focus-visible { outline: 2px solid var(--laurel-focus); }
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup) input[type="radio"]:not(:checked) { color: var(--laurel-brass-deep); accent-color: var(--laurel-brass); }
