/* SOURCE: src/windows/w14-mobile.css */
/* W14 手机合同：默认 390px，不要求手机图片。 */
@media (max-width: 700px) {
    #chat {
        padding: var(--laurel-gap-xs);
    }

    #chat .mes {
        margin-block: var(--laurel-gap-sm);
        padding: var(--laurel-gap-sm);
    }

    #chat .mes[is_user="true"] {
        margin-inline-start: 1.4rem;
    }

    #chat .mesAvatarWrapper {
        margin-inline-end: var(--laurel-gap-sm);
    }

    #chat .mes_text {
        max-width: 100%;
        line-height: 1.78;
    }

    #top-settings-holder {
        min-height: 40px;
        gap: 2px;
        padding-inline: 2px;
    }

    #top-settings-holder .drawer-toggle {
        min-inline-size: 34px;
        min-block-size: 36px;
        padding: 3px;
    }

    #send_form {
        gap: var(--laurel-gap-xs);
        padding: var(--laurel-gap-xs);
    }

    #send_form .menu_button,
    #send_but {
        min-width: 38px;
        min-height: 38px;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) .drawer-content {
        width: 100%;
        max-width: 100%;
        padding: var(--laurel-gap-sm);
    }
}

